Given a head of Singly Linked List, we have to print all the elements in the list.Examples:Input: Output: 1->2->3->4->5Input:  Output: 10->20->30->40->50Try It YourselfTable of Content[Approach 1] Using Iterative Method  - O(n) Time and O(1) Space[Approach 2] Using Recursion Method- O(n) Time and O(n) Space[Approach 1] Using Iterative Method  - O(n) Time and O(1) Space Start from the head and follow the next pointer to visit each node, printing the data until the next pointer is NULL.Steps to solve the problem:Start from the head node.While the current node is not NULL:Print the node's data.Move to the next node using the next pointerProgram to Print the Singly Linked List using Iteration.
            C++

    #include <iostream>

using namespace std;

// A linked list node
class Node {
public:
    int data;
    Node* next;

    // Constructor to initialize a new node with data
    Node(int new_data) {
        this->data = new_data;
        this->next = nullptr;
    }
};

// Function to print the singly linked list
void printList(Node* head) {

    // A loop that runs till head is nullptr
    while (head != nullptr) {

        // Printing data of current node
        cout << head->data ;
        if(head->next)
        cout<<"->";

        // Moving to the next node
        head = head->next;
    }
}

int main() {

    // Create a linked list: 10 -> 20 -> 30 -> 40
    Node* head = new Node(10);
    head->next = new Node(20);
    head->next->next = new Node(30);
    head->next->next->next = new Node(40);

    printList(head);

    return 0;
}


